"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["22779"],{78661(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.item_de_avaliacao.pontuacao_fora_do_passo","status":422,"titulo":"A pontua\xe7\xe3o m\xe1xima do item deve ser m\xfaltipla do passo do lan\xe7amento"},"descricao":{"codigo":"uniplus.selecao.item_de_avaliacao.pontuacao_fora_do_passo","requisitos":["UNI-REQ-0175"],"oQueAconteceu":["A etapa declara um `passoDoLancamento` (por exemplo, 0,5) e a pontua\xe7\xe3o m\xe1xima de um\\nitem n\xe3o \xe9 m\xfaltipla dele (por exemplo, 2,3). O avaliador s\xf3 pode lan\xe7ar notas em\\nm\xfaltiplos do passo, e um item cuja pontua\xe7\xe3o m\xe1xima n\xe3o \xe9 m\xfaltipla dele nunca poderia\\nreceber a nota inteira.","A recusa vale j\xe1 na grava\xe7\xe3o, tamb\xe9m em rascunho, e chega no array `errors[]`, no campo\\n`itensDeAvaliacao[i].pontuacaoMaxima` da etapa."],"comoResolver":["Ajuste a pontua\xe7\xe3o do item para um m\xfaltiplo do passo, ou altere o passo da etapa. Se a\\nbanca escolhe o n\xedvel de atendimento em vez de digitar a nota, remova o passo: com\\nescala de atendimento a etapa n\xe3o declara passo.","Se a resposta trouxer mais de uma viola\xe7\xe3o em `errors[]`, corrija todas antes de\\nreenviar."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Item de avaliacao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);